style.css:
@-moz-document domain("example.com") {
/* Change background to dark grey */
    body {
        background-color: #222 !important;
        color: #fff !important;
    }
    /* Hide specific elements */
    .sidebar, #footer {
        display: none !important;
    }
    /* Style links */
    a {
        color: #00bcd4 !important;
    }
}
